FUNCTION handleDeleteColumn(request, column_id):
    // REQ-5-021; preconditions: existing column and persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF tickets exist THEN ROLLBACK; RETURN 409. END IF MARK deleted and renumber; COMMIT; RETURN 204.
    // REQ-5-008; non-idempotent; rollback leaves orders and relations unchanged.

FUNCTION handleDeleteProject(request, project_id):
    // REQ-5-016; preconditions: existing project and persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF columns or tickets remain THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-5-008; repeat is 404; rollback leaves all state unchanged.

FUNCTION handlePatchColumn(request, column_id):
    // REQ-5-020; preconditions: JSON, existing column, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock project columns and tickets; IF duplicate name or new WIP below count then ROLLBACK; RETURN 409. END IF UPDATE and renumber; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback preserves all orders and relations.

FUNCTION handlePatchProject(request, project_id):
    // REQ-5-015; preconditions: JSON, existing project, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE result OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF duplicate key or deactivation has active columns or tickets THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback preserves relations and order.

FUNCTION handleCreateProject(request):
    // REQ-5-013; preconditions: JSON and persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE REQ-5-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF key exists THEN ROLLBACK; RETURN 409. END IF CREATE caller-owned project; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves all future column and ticket relations.

FUNCTION handleCreateColumn(request, project_id):
    // REQ-5-018; preconditions: JSON, active project, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE REQ-5-003 OR RETURN 400 or 422; absent project is 404.
    BEGIN TRANSACTION; lock project columns; IF duplicate name or invalid insertion position THEN ROLLBACK; RETURN 409. END IF INSERT and renumber; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves all column and ticket order.

FUNCTION handleBulkMoveTickets(request, project_id):
    // REQ-5-026; preconditions: JSON, existing project, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE list cardinality, distinct ids, target, placement OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock all source and target columns. IF any ticket or target missing THEN ROLLBACK; RETURN 404; IF cross-project or WIP rule fails THEN ROLLBACK; RETURN 409. END IF reorder all requested tickets; COMMIT; RETURN 200.
    // REQ-5-007; identical final order idempotent; rollback restores every original position.

FUNCTION handleCreateTicket(request):
    // REQ-5-023; preconditions: JSON, active project and column, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE body OR RETURN 400 or 422; absent relation is 404.
    BEGIN TRANSACTION; lock column; IF WIP reached or column not in project THEN ROLLBACK; RETURN 409. END IF APPEND ticket; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves positions and relations.

FUNCTION handleMoveTicket(request, ticket_id):
    // REQ-5-025; preconditions: JSON, existing ticket, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE ids OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock source and target columns; IF target relation missing THEN ROLLBACK; RETURN 404; IF project mismatch, invalid after ticket, or WIP failure THEN ROLLBACK; RETURN 409. END IF reorder contiguously; COMMIT; RETURN 200.
    // REQ-5-005; identical resulting position idempotent and rollback preserves all order.
